// Build conversation message for Claude.
// Telegram message arrives at $json.message
const msg = $json.message;
const text = msg?.text || '';
const chatId = msg?.chat?.id?.toString();
const username = msg?.from?.username || msg?.from?.first_name || 'User';

// Simple command routing
if (text.startsWith('/soccer')) {
  return [{ json: {
    chatId,
    username,
    userMessage: text.replace('/soccer', '').trim() || 'Generate a soccer reel script for today',
    systemPrompt: 'You are a YouTube Shorts scriptwriter for soccer viral content. Generate reel scripts following this formula: HOOK (0-5s referencing a current match) → STORY (45-60s historical scandal) → PEAK ANSWER (the reveal). Be concise — this is a chat response, not a full document.',
    mode: 'soccer'
  }}];
}

// Default: general Claude conversation
return [{ json: {
  chatId,
  username,
  userMessage: text,
  systemPrompt: 'You are a helpful, knowledgeable assistant. Be direct and concise. The user is messaging via Telegram.',
  mode: 'chat'
}}];

const claudeOut = $input.first().json;
const upstream = $('Route Message').first().json;

const reply = claudeOut.content?.[0]?.text || 'Sorry, something went wrong.';

return [{ json: {
  chatId: upstream.chatId,
  reply,
  inputTokens: claudeOut.usage?.input_tokens || 0,
  outputTokens: claudeOut.usage?.output_tokens || 0
}}];
